const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto");
const prefix="docs/coordinator/worktree-completion/evidence/dcc1-parity-observer-preflight-corrected";
const record=JSON.parse(fs.readFileSync("docs/coordinator/worktree-completion/evidence/dcc1-parity-observer-preflight-correction.json","utf8"));
const command=record.correctedCommand;
if(!command.startsWith("node <<'NODE'\n")||!command.endsWith("\nNODE"))throw Error("unexpected retained command envelope");
const source=command.slice("node <<'NODE'\n".length,-"\nNODE".length);
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
for(const path of [prefix+".raw.log",prefix+".meta.jsonl"])if(fs.existsSync(path))throw Error("exclusive output already exists: "+path);
const raw=fs.openSync(prefix+".raw.log","wx",0o600),meta=fs.openSync(prefix+".meta.jsonl","wx",0o600);
const put=x=>{fs.writeSync(meta,JSON.stringify(x)+"\n");fs.fsyncSync(meta)};
put({event:"start",at:new Date().toISOString(),classification:"Read-only corrected inventory; direct merged process bytes, not browser/test output",cwd:process.cwd(),executable:process.execPath,args:[],stdinSourceSha256:sha(source),retainedCommand:command});
const child=cp.spawn(process.execPath,[],{cwd:process.cwd(),stdio:["pipe","pipe","pipe"]});
const chunks=[];let loggerError;
const accept=b=>{chunks.push(b);try{fs.writeSync(raw,b);fs.fsyncSync(raw)}catch(e){loggerError=String(e)}};
child.stdout.on("data",accept);child.stderr.on("data",accept);child.stdin.end(source);
child.on("error",e=>{loggerError=String(e)});
child.on("close",(code,signal)=>{const bytes=Buffer.concat(chunks);let result,parseError;
try{result=JSON.parse(bytes.toString("utf8"))}catch(e){parseError=String(e)}
put({event:"terminal",at:new Date().toISOString(),exit:code,signal,loggerExit:loggerError?1:0,loggerError,bytes:bytes.length,sha256:sha(bytes),parseError});
fs.closeSync(raw);fs.closeSync(meta);
console.log(JSON.stringify({exit:code,signal,loggerExit:loggerError?1:0,bytes:bytes.length,sha256:sha(bytes),parseError,result:result&&{index:result.index,executionClosure:result.executionClosure,trackedCount:result.trackedCount,untrackedCount:result.untracked.length,retainedCount:result.retainedCount,preserveCount:result.preserve.length,failures:result.failures,pass:result.pass,npmGraphSha256:result.npmGraphSha256,commandCount:result.commands.length,nonzeroCommands:result.commands.filter(x=>x.exit!==0)}}));
process.exitCode=loggerError||parseError?2:code===null?2:code;});
